package com.evbloat;

import net.runelite.api.gameval.NpcID;

final class BloatIds
{
	private BloatIds() {}
	static boolean matches(int id)
	{
		return id == NpcID.TOB_BLOAT || id == NpcID.TOB_BLOAT_STORY || id == NpcID.TOB_BLOAT_HARD;
	}
}

package com.evbloat;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Alpha;
import java.awt.Color;

@ConfigGroup(EVBloatConfig.GROUP)
public interface EVBloatConfig extends Config
{
	String GROUP = "evbloat";
	@ConfigItem(keyName = "keepOriginals", name = "Show original Bloat too",
		description = "Draw both models to compare visuals and targeting during testing.", position = 0)
	default boolean keepOriginals() { return false; }

	@ConfigItem(keyName = "outline", name = "Outline EV Bloat",
		description = "Outline EVScape's actual model independently of the regular Bloat outline.", position = 4)
	default boolean outline() { return false; }

	@Alpha
	@ConfigItem(keyName = "outlineColor", name = "EV outline color",
		description = "Color of the outline around EVScape's actual model.", position = 5)
	default Color outlineColor() { return Color.YELLOW; }

	@ConfigItem(keyName = "outlineRegularBloat", name = "Outline Regular Bloat",
		description = "Show an outline of the real Bloat alongside EVScape. Disable to hide this plugin's regular Bloat outline.", position = 6)
	default boolean outlineRegularBloat() { return true; }

	@Alpha
	@ConfigItem(keyName = "regularBloatOutlineColor", name = "Bloat outline color",
		description = "Color of the regular Bloat outline.", position = 7)
	default Color regularBloatOutlineColor() { return Color.CYAN; }

	@ConfigItem(keyName = "renameBloat", name = "Rename Bloat to EVScape",
		description = "Display EVScape in Bloat's hover and right-click menu targets. Keeps the original NPC and actions.", position = 8)
	default boolean renameBloat() { return false; }

	@ConfigItem(keyName = "originalBloatSlouch", name = "Original Bloat Slouch",
		description = "Use an upright torso, drooping head, relaxed arms and bent knees inspired by Bloat's native pose. Off keeps the funny standing villager bend. This is a procedural approximation, not the native skeleton.", position = 9)
	default boolean originalBloatSlouch() { return false; }
}

package com.evbloat;

import java.util.Set;
import java.util.function.Predicate;
import java.util.function.BiPredicate;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Model;
import net.runelite.api.Projection;
import net.runelite.api.Renderable;
import net.runelite.api.Scene;
import net.runelite.api.SceneTileModel;
import net.runelite.api.SceneTilePaint;
import net.runelite.api.Texture;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.hooks.DrawCallbacks;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/** Filters original GPU geometry while leaving the NPC in the native scene/picking traversal. */
final class EVBloatDrawCallbacks implements DrawCallbacks
{
	private static final Logger log = LoggerFactory.getLogger(EVBloatDrawCallbacks.class);
	private final Client client;
	private final DrawCallbacks delegate;
	private final Predicate<Renderable> conceal;
	private final BiPredicate<Renderable, Model> concealModel;
	private final Runnable frameComplete;

	EVBloatDrawCallbacks(Client client, DrawCallbacks delegate, Predicate<Renderable> conceal)
	{
		this(client, delegate, conceal, () -> {});
	}

	EVBloatDrawCallbacks(Client client, DrawCallbacks delegate, Predicate<Renderable> conceal, Runnable frameComplete)
	{
		this(client, delegate, conceal, (r, m) -> conceal.test(r), frameComplete);
	}

	EVBloatDrawCallbacks(Client client, DrawCallbacks delegate, Predicate<Renderable> conceal,
		BiPredicate<Renderable, Model> concealModel, Runnable frameComplete)
	{
		this.client = client;
		this.delegate = delegate;
		this.conceal = conceal;
		this.concealModel = concealModel;
		this.frameComplete = frameComplete;
	}

	DrawCallbacks delegate() { return delegate; }

	@Override
	public void draw(Projection p, Scene s, Renderable r, int orientation, int x, int y, int z, long hash)
	{
		// Legacy GPU renderers perform picking inside their draw callback. Preserve
		// that exact projection, native model, position and tag before skipping pixels.
		if (conceal.test(r))
		{
			try
			{
				Model original = r.getModel();
				if (original != null && concealModel.test(r, original))
				{
					r.setModelHeight(original.getModelHeight());
					client.checkClickbox(p, original, orientation, x, y, z, hash);
					return;
				}
			}
			catch (RuntimeException ex)
			{
				log.debug("EV Bloat legacy picking unavailable; forwarding original draw", ex);
			}
		}
		delegate.draw(p,s,r,orientation,x,y,z,hash);
	}

	@Override
	public void drawTemp(Projection p, Scene s, GameObject object, Model model, int orientation, int x, int y, int z)
	{
		// Zone rendering: the native scene checks the unchanged model immediately
		// after this callback (including threaded actor jobs). Do not touch picking.
		if (object != null && concealModel.test(object.getRenderable(), model)) { return; }
		delegate.drawTemp(p,s,object,model,orientation,x,y,z);
	}

	@Override
	public void drawDynamic(Projection p, Scene s, TileObject object, Renderable r, Model m, int o, int x, int y, int z)
	{
		if (!concealModel.test(r, m)) { delegate.drawDynamic(p,s,object,r,m,o,x,y,z); }
	}

	@Override
	public void drawDynamic(int thread, Projection p, Scene s, TileObject object, Renderable r, Model m, int o, int x, int y, int z)
	{
		if (!concealModel.test(r, m)) { delegate.drawDynamic(thread,p,s,object,r,m,o,x,y,z); }
	}

	// Forward every other renderer hook, including scene lifecycle and frustum
	// queries. Never change GPU flags, render threads, projections, or model arrays.
	@Override
	public void draw(int color)
	{
		try
		{
			delegate.draw(color);
		}
		finally
		{
			// Give the renderer its callback identity back between frames, including
			// before queued shutdown/startup work and when presentation fails.
			frameComplete.run();
		}
	}
	@Override public void drawScenePaint(Scene s, SceneTilePaint p, int plane, int x, int z) { delegate.drawScenePaint(s,p,plane,x,z); }
	@Override public void drawSceneTileModel(Scene s, SceneTileModel m, int x, int z) { delegate.drawSceneTileModel(s,m,x,z); }
	@Override public void drawScene(double x,double y,double z,double pitch,double yaw,int plane) { delegate.drawScene(x,y,z,pitch,yaw,plane); }
	@Override public void postDrawScene() { delegate.postDrawScene(); }
	@Override public void animate(Texture texture,int diff) { delegate.animate(texture,diff); }
	@Override public void loadScene(Scene s) { delegate.loadScene(s); }
	@Override public void swapScene(Scene s) { delegate.swapScene(s); }
	@Override public boolean tileInFrustum(Scene s,float px,float py,float yx,float yy,int x,int y,int z,int h,int zoom,int plane) { return delegate.tileInFrustum(s,px,py,yx,yy,x,y,z,h,zoom,plane); }
	@Override public boolean zoneInFrustum(int plane,int x,int z,int pass) { return delegate.zoneInFrustum(plane,x,z,pass); }
	@Override public void loadScene(WorldView w,Scene s) { delegate.loadScene(w,s); }
	@Override public void despawnWorldView(WorldView w) { delegate.despawnWorldView(w); }
	@Override public void preSceneDraw(Scene s,Projection p,float x,float y,float z,float pitch,float yaw,int plane,int a,int b,Set<Integer> roofs) { delegate.preSceneDraw(s,p,x,y,z,pitch,yaw,plane,a,b,roofs); }
	@Override public void preSceneDraw(Scene s,float x,float y,float z,float pitch,float yaw,int plane,int a,int b,Set<Integer> roofs) { delegate.preSceneDraw(s,x,y,z,pitch,yaw,plane,a,b,roofs); }
	@Override public void postSceneDraw(Scene s) { delegate.postSceneDraw(s); }
	@Override public void drawPass(Projection p,Scene s,int pass) { delegate.drawPass(p,s,pass); }
	@Override public void drawZoneOpaque(Projection p,Scene s,int x,int z) { delegate.drawZoneOpaque(p,s,x,z); }
	@Override public void drawZoneAlpha(Projection p,Scene s,int x,int z,int pass) { delegate.drawZoneAlpha(p,s,x,z,pass); }
	@Override public void invalidateZone(Scene s,int x,int z) { delegate.invalidateZone(s,x,z); }
}

package com.evbloat;

import javax.inject.Inject;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.gameval.AnimationID;

/** Retimes the original artwork's stepping cycle to Bloat's live animation frame. */
final class EVBloatGait
{
	private final Client client;

	@Inject
	EVBloatGait(Client client) { this.client = client; }

	int frame(NPC npc, int fallback)
	{
		boolean action = npc.getAnimation() == AnimationID.TOB_BLOAT_WALK;
		if (!action && !isWalkPose(npc)) { return fallback; }
		int id = action ? npc.getAnimation() : npc.getPoseAnimation();
		if (id <= 0) { return fallback; }
		Animation animation = client.loadAnimation(id);
		if (animation == null) { return fallback; }
		int nativeFrame = action ? npc.getAnimationFrame() : npc.getPoseAnimationFrame();
		return frame(animation, nativeFrame, fallback);
	}

	static boolean isWalkPose(NPC npc)
	{
		int pose = npc.getPoseAnimation();
		return pose == AnimationID.TOB_BLOAT_WALK || (pose > 0 &&
			(pose == npc.getWalkAnimation() || pose == npc.getWalkRotateLeft()
			|| pose == npc.getWalkRotateRight() || pose == npc.getWalkRotate180()));
	}

	int slouchFrame(NPC npc)
	{
		Animation animation = client.loadAnimation(npc.getAnimation());
		return animation == null ? 0 : frame(animation, npc.getAnimationFrame(), 0);
	}

	static int frame(Animation animation, int nativeFrame, int fallback)
	{
		// Some interpolation paths pack a cycle counter into a negative frame.
		if (nativeFrame < 0) { nativeFrame &= 0xffff; }
		int count = animation.getNumFrames();
		if (count <= 0 || nativeFrame >= count) { return fallback; }
		int[] lengths = animation.getFrameLengths();
		if (animation.isMayaAnim() || lengths == null || lengths.length != count)
		{
			return nativeFrame * EVBloatModelFactory.FRAME_COUNT / count;
		}
		long total = 0, elapsed = 0;
		for (int i = 0; i < count; i++)
		{
			if (lengths[i] <= 0) { return fallback; }
			total += lengths[i];
			if (i < nativeFrame) { elapsed += lengths[i]; }
		}
		return (int) (elapsed * EVBloatModelFactory.FRAME_COUNT / total);
	}
}

package com.evbloat;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Original low-poly artwork: negative Y is up; the face looks toward negative Z. */
final class EVBloatMesh
{
	static final int SHIRT = 0, TROUSERS = 1, SKIN = 2, HAIR = 3,
		BELT = 4, BOOTS = 5, EYES = 6, LACES = 7;
	static final int SWARM_FACES = 60;
	private final List<Triangle> faces = new ArrayList<>();

	List<Triangle> getFaces() { return Collections.unmodifiableList(faces); }

	static EVBloatMesh pose(double phase, boolean walking, boolean down)
	{
		return pose(phase, walking, down, false);
	}

	static EVBloatMesh pose(double phase, boolean walking, boolean down, boolean kneeling)
	{
		EVBloatMesh mesh = new EVBloatMesh();
		double bob = walking ? Math.cos(phase * 2) * 3 : Math.sin(phase) * 1.5;
		double belly = Math.sin(phase + 0.5) * (walking ? 4 : 1.5);
		// Closed rings keep the silhouette broad and the waist narrower than the belly.
		mesh.rings(new double[][] {
			{0, -103 + bob, 0, 81, 57}, {0, -132 + bob, -6, 104, 73},
			{belly, -184 + bob, -12, 117, 86}, {belly * 0.5, -226 + bob, -5, 110, 72},
			{0, -265 + bob, 0, 89, 52}, {0, -285 + bob, 0, 55, 37}
		}, 10, SHIRT);
		mesh.rings(new double[][] {
			{0, -98 + bob, 0, 83, 57}, {0, -106 + bob, 0, 84, 58}
		}, 10, BELT);

		for (int side : new int[]{-1, 1})
		{
			// Planted stance followed by a lifted return step, rather than sliding both soles.
			double cycle = (phase / (Math.PI * 2) + (side == 1 ? 0.5 : 0)) % 1;
			if (cycle < 0) { cycle++; }
			double swingPhase = Math.max(0, (cycle - 0.6) / 0.4);
			double step = !walking ? 0 : cycle < 0.6 ? -38 + 76 * cycle / 0.6
				: 38 * Math.cos(Math.PI * swingPhase);
			double lift = walking ? 24 * Math.sin(Math.PI * swingPhase) : 0;
			mesh.rings(new double[][] {
				{side * 39, -112 + bob, 0, 42, 43},
				{side * 44, -90 - lift * 0.25, step * 0.3, 45, 42},
				{side * 48, -62 - lift * 0.6, step * 0.7 - lift * 0.3, 38, 35},
				{side * 48, -35 - lift, step, 27, 27}
			}, 6, TROUSERS);
			mesh.rings(new double[][] {
				{side * 48, -38 - lift, step, 28, 27},
				{side * 48, -20 - lift, step - 8, 29, 38},
				{side * 48, -2 - lift, step - 13, 29, 43}
			}, 6, BOOTS);
			mesh.ellipsoid(side * 94, -251 + bob, 0, 42, 35, 43, 6, 4, SHIRT);
			double swing = walking ? -step * 0.6 : 0;
			mesh.ellipsoid(side * 114, -215 + bob, swing, 26, 39, 28, 6, 4, SKIN);
			mesh.ellipsoid(side * 128, -177 + bob, swing * 1.4, 23, 35, 25, 6, 4, SKIN);
			mesh.ellipsoid(side * 135, -137 + bob, swing * 1.6, 18, 20, 20, 6, 4, SKIN);
		}
		mesh.ellipsoid(0, -283 + bob, -4, 39, 22, 31, 8, 4, SKIN);
		mesh.ellipsoid(0, -320 + bob, 4, 40, 44, 33, 8, 6, HAIR);
		mesh.ellipsoid(0, -310 + bob, -12, 34, 35, 28, 8, 6, SKIN);
		for (int side : new int[]{-1, 1})
		{
			mesh.ellipsoid(side * 36, -314 + bob, -1, 7, 13, 10, 6, 3, SKIN);
		}
		// Hair cap and sideburns leave the face exposed.

		for (int side : new int[]{-1, 1})
		{
			mesh.ellipsoid(side * 33, -329 + bob, 5, 8, 20, 22, 6, 4, HAIR);
			mesh.patch(new Vec[]{new Vec(side * 8, -326 + bob, -34),
				new Vec(side * 19, -325 + bob, -32), new Vec(side * 14, -323 + bob, -35)}, EYES);
			// Downturned moustache, matching the supplied green character.
			mesh.patch(new Vec[]{new Vec(0, -307 + bob, -39),
				new Vec(side * 13, -309 + bob, -37), new Vec(side * 23, -299 + bob, -34),
				new Vec(side * 7, -302 + bob, -40)}, HAIR);
		}
		mesh.ellipsoid(0, -315 + bob, -36, 7, 10, 8, 6, 3, SKIN);
		mesh.patch(new Vec[]{new Vec(-9, -294 + bob, -33), new Vec(9, -294 + bob, -33),
			new Vec(8, -292 + bob, -33), new Vec(-8, -292 + bob, -33)}, BELT);
		// Three brown crosses sit directly above the belly, like the reference tunic.
		for (int row = 0; row < 3; row++)
		{
			double y = -253 + bob + row * 14;
			double z = -64 - row * 7.5;
			mesh.patch(new Vec[]{new Vec(-10, y - 4, z), new Vec(10, y + 4, z),
				new Vec(10, y + 1, z - 1), new Vec(-10, y - 7, z - 1)}, LACES);
			mesh.patch(new Vec[]{new Vec(-10, y + 4, z), new Vec(10, y - 4, z),
				new Vec(10, y - 7, z - 1), new Vec(-10, y + 1, z - 1)}, LACES);
		}
		if (down)
		{
			// Sleeping Bloat remains upright and slumps forward; keep both feet planted.
			List<Triangle> fallen = new ArrayList<>();
			for (Triangle face : mesh.faces)
			{
				fallen.add(new Triangle(kneeling ? kneel(face.a, face.color) : slump(face.a),
					kneeling ? kneel(face.b, face.color) : slump(face.b),
					kneeling ? kneel(face.c, face.color) : slump(face.c), face.color));
			}
			mesh.faces.clear();
			mesh.faces.addAll(fallen);
		}
		mesh.swarm(phase);
		return mesh;
	}

	private static Vec slump(Vec v)
	{
		if (v.y >= -108) { return v; }
		double angle = Math.toRadians(38), y = v.y + 108;
		return new Vec(v.x, -108 + y * Math.cos(angle) - v.z * Math.sin(angle),
			y * Math.sin(angle) + v.z * Math.cos(angle));
	}

	/** Upright torso and an independently drooping head, like the native silhouette. */
	private static Vec kneel(Vec v, int color)
	{
		if (color == BOOTS) { return v; }
		if (color == TROUSERS)
		{
			double t = Math.max(0, Math.min(1, (-v.y - 35) / 77));
			return new Vec(v.x, v.y + 20 * t, v.z - 24 * Math.sin(t * Math.PI));
		}
		boolean head = v.y < -275 && (color == SKIN || color == HAIR || color == EYES || color == BELT);
		double y = v.y, z = v.z, x = v.x;
		if (head)
		{
			// Neck hinge: bow the face without pitching the belly toward the floor.
			double neckY = y + 283, angle = Math.toRadians(32);
			y = -283 + neckY * Math.cos(angle) - z * Math.sin(angle);
			z = neckY * Math.sin(angle) + z * Math.cos(angle);
		}
		else if (color == SKIN && Math.abs(x) > 85)
		{
			// Relax the forearms inward; hands remain low beside the belly.
			double relax = Math.max(0, Math.min(1, (v.y + 250) / 115));
			x -= Math.signum(x) * 16 * relax;
			z -= 8 * relax;
		}
		double angle = Math.toRadians(8), hipY = y + 108;
		return new Vec(x, -88 + hipY * Math.cos(angle) - z * Math.sin(angle),
			hipY * Math.sin(angle) + z * Math.cos(angle));
	}

	/** Purely cosmetic insects, independent of native renderer effect batching. */
	private void swarm(double phase)
	{
		for (int i = 0; i < 10; i++)
		{
			double a = phase + i * Math.PI * 2 / 10;
			double radius = 175 + 15 * Math.sin(phase * 3 + i);
			double x = radius * Math.cos(a), z = radius * Math.sin(a);
			double y = -190 + 65 * Math.sin(phase * 2 + i * 1.7);
			double flap = 3 + 2 * Math.sin(phase * 8 + i);
			triangle(new Vec(x - 3,y,z - 5), new Vec(x + 3,y,z - 5), new Vec(x,y - 3,z + 5), EYES);
			triangle(new Vec(x,y,z), new Vec(x - 9,y - flap,z - 2), new Vec(x - 8,y - flap,z + 4), SKIN);
			triangle(new Vec(x,y,z), new Vec(x + 9,y - flap,z - 2), new Vec(x + 8,y - flap,z + 4), SKIN);
		}
	}

	private void ellipsoid(double x, double y, double z, double rx, double ry, double rz,
		int sides, int layers, int color)
	{
		Vec top = new Vec(x, y - ry, z), bottom = new Vec(x, y + ry, z);
		Vec[][] rings = new Vec[layers - 1][sides];
		for (int layer = 1; layer < layers; layer++)
		{
			double latitude = Math.PI * layer / layers;
			for (int side = 0; side < sides; side++)
			{
				double angle = Math.PI * 2 * side / sides;
				rings[layer - 1][side] = new Vec(x + Math.sin(latitude) * Math.cos(angle) * rx,
					y - Math.cos(latitude) * ry, z + Math.sin(latitude) * Math.sin(angle) * rz);
			}
		}
		for (int side = 0; side < sides; side++)
		{
			int next = (side + 1) % sides;
			triangle(top, rings[0][next], rings[0][side], color);
			triangle(bottom, rings[rings.length - 1][side], rings[rings.length - 1][next], color);
		}
		joinRings(rings, color);
	}

	private void rings(double[][] specs, int sides, int color)
	{
		Vec[][] rings = new Vec[specs.length][sides];
		for (int row = 0; row < specs.length; row++)
		{
			double[] s = specs[row];
			for (int side = 0; side < sides; side++)
			{
				double angle = Math.PI * 2 * side / sides;
				rings[row][side] = new Vec(s[0] + Math.cos(angle) * s[3], s[1], s[2] + Math.sin(angle) * s[4]);
			}
		}
		joinRings(rings, color);
		for (int side = 0; side < sides; side++)
		{
			int next = (side + 1) % sides;
			triangle(new Vec(specs[0][0], specs[0][1], specs[0][2]), rings[0][side], rings[0][next], color);
			int last = specs.length - 1;
			triangle(new Vec(specs[last][0], specs[last][1], specs[last][2]), rings[last][next], rings[last][side], color);
		}
	}

	private void joinRings(Vec[][] rings, int color)
	{
		for (int row = 0; row < rings.length - 1; row++)
		{
			for (int side = 0; side < rings[row].length; side++)
			{
				int next = (side + 1) % rings[row].length;
				triangle(rings[row][side], rings[row][next], rings[row + 1][next], color);
				triangle(rings[row][side], rings[row + 1][next], rings[row + 1][side], color);
			}
		}
	}

	private void patch(Vec[] points, int color)
	{
		for (int i = 1; i < points.length - 1; i++) { triangle(points[0], points[i], points[i + 1], color); }
	}

	private void triangle(Vec a, Vec b, Vec c, int color)
	{
		// Both windings make the procedural panels robust in all renderers.
		faces.add(new Triangle(a, b, c, color));
		faces.add(new Triangle(c, b, a, color));
	}

	static final class Triangle
	{
		final Vec a, b, c;
		final int color;
		Triangle(Vec a, Vec b, Vec c, int color) { this.a = a; this.b = b; this.c = c; this.color = color; }
	}

	static final class Vec
	{
		final double x, y, z;
		Vec(double x, double y, double z) { this.x = x; this.y = y; this.z = z; }
	}
}

package com.evbloat;

import java.util.Arrays;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.JagexColor;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;

/** Uses a cache triangle only as an allocation primitive; no cache arrays are modified. */
final class EVBloatModelFactory
{
	// Cache model 823 is a single untextured triangle (3 vertices, 1 face).
	private static final int TRIANGLE_MODEL = 823;
	private static final short[] COLORS = {
		JagexColor.packHSL(23, 4, 46), JagexColor.packHSL(22, 4, 51),
		JagexColor.packHSL(6, 3, 76), JagexColor.packHSL(29, 3, 35),
		JagexColor.packHSL(3, 5, 26), JagexColor.packHSL(17, 6, 29),
		JagexColor.packHSL(0, 0, 13), JagexColor.packHSL(3, 5, 26)
	};
	static final int FRAME_COUNT = 32;
	// Native projection arrays have 6500 entries. Reserve headroom for all renderers.
	static final int MAX_VERTICES = 6400;
	static final int MAX_FACES = 2133;
	// Share immutable poses across replacements. No per-tick mesh allocation.
	private static final EVBloatMesh[][] POSES = makePoses();
	static final double BASE_HEIGHT = baseHeight();
	private final Client client;
	private ModelData template;

	@Inject
	EVBloatModelFactory(Client client)
	{
		this.client = client;
	}

	Model create(int mode, int phase)
	{
		return create(mode, phase, 1);
	}

	Model create(int mode, int phase, double scale)
	{
		EVBloatMesh pose = POSES[mode][Math.floorMod(phase, FRAME_COUNT)];
		int faceCount = pose.getFaces().size();
		if (faceCount > MAX_FACES || faceCount * 3 > MAX_VERTICES)
		{
			throw new IllegalStateException("EV Bloat exceeds native model buffer capacity");
		}
		if (template == null)
		{
			ModelData seed = client.loadModelData(TRIANGLE_MODEL);
			if (seed == null)
			{
				return null; // Asset download may still be in progress; the plugin retries.
			}
			if (seed.getVerticesCount() != 3 || seed.getFaceCount() != 1)
			{
				throw new IllegalStateException("Cache triangle 823 changed; originals will stay visible");
			}
			ModelData[] parts = new ModelData[pose.getFaces().size()];
			for (int i = 0; i < parts.length; i++)
			{
				// mergeModels deduplicates matching coordinates. Separate each seed by
				// a large translation so each output triangle owns three vertices.
				parts[i] = seed.shallowCopy().cloneVertices().translate(i * 1024, 0, 0);
			}
			template = client.mergeModels(parts);
			if (template.getFaceCount() != parts.length || template.getVerticesCount() != parts.length * 3)
			{
				template = null;
				throw new IllegalStateException("Unexpected triangle merge shape; originals will stay visible");
			}
		}
		ModelData data = template.shallowCopy().cloneVertices().cloneColors()
			.cloneTransparencies(true);
		// Untextured cache models have no texture array; cloneTextures requires one.
		if (data.getFaceTextures() != null)
		{
			data.cloneTextures();
		}
		writeVertices(data.getVerticesX(), data.getVerticesY(), data.getVerticesZ(),
			data.getFaceIndices1(), data.getFaceIndices2(), data.getFaceIndices3(), pose, scale);
		for (int i = 0; i < data.getFaceCount(); i++)
		{
			data.getFaceColors()[i] = COLORS[pose.getFaces().get(i).color];
		}
		Arrays.fill(data.getFaceTransparencies(), (byte) 0);
		if (data.getFaceTextures() != null)
		{
			Arrays.fill(data.getFaceTextures(), (short) -1);
		}
		// Invalidate any cached geometry metadata after direct coordinate writes.
		data.scale(128, 128, 128);
		Model model = data.light();
		model.calculateBoundsCylinder();
		return model;
	}

	static int frame(double seconds, int phase)
	{
		return Math.floorMod((int) (seconds * 4.5 * FRAME_COUNT / (Math.PI * 2)) + phase, FRAME_COUNT);
	}

	static void animate(Model model, int mode, int frame)
	{
		animate(model, mode, frame, 1);
	}

	static void animate(Model model, int mode, int frame, double scale)
	{
		animate(model, mode, frame, scale, frame);
	}

	static void animate(Model model, int mode, int frame, double scale, int flyFrame)
	{
		animate(model, mode, frame, scale, flyFrame, null, false);
	}

	static void animate(Model model, int mode, int frame, double scale, int flyFrame,
		EVBloatNativeMotion.Sample nativeMotion, boolean originalSlouch)
	{
		writeVertices(model.getVerticesX(), model.getVerticesY(), model.getVerticesZ(),
			model.getFaceIndices1(), model.getFaceIndices2(), model.getFaceIndices3(),
			POSES[mode][Math.floorMod(frame, FRAME_COUNT)], scale);
		if (nativeMotion != null)
		{
			List<EVBloatMesh.Triangle> upright = POSES[0][Math.floorMod(frame,FRAME_COUNT)].getFaces();
			List<EVBloatMesh.Triangle> down = POSES[originalSlouch ? 3 : 2][Math.floorMod(frame,FRAME_COUNT)].getFaces();
			for(int face=0;face<upright.size()-EVBloatMesh.SWARM_FACES;face++)
			{
				EVBloatMesh.Triangle u=upright.get(face),d=down.get(face);
				motionVertex(model,model.getFaceIndices1()[face],u.a,d.a,u.color,scale,nativeMotion);
				motionVertex(model,model.getFaceIndices2()[face],u.b,d.b,u.color,scale,nativeMotion);
				motionVertex(model,model.getFaceIndices3()[face],u.c,d.c,u.color,scale,nativeMotion);
			}
		}
		// Swarm continues buzzing even when the NPC holds its sleep animation frame.
		List<EVBloatMesh.Triangle> swarm = POSES[0][Math.floorMod(flyFrame, FRAME_COUNT)].getFaces();
		for (int i = swarm.size() - EVBloatMesh.SWARM_FACES; i < swarm.size(); i++)
		{
			EVBloatMesh.Triangle face = swarm.get(i);
			put(model.getVerticesX(),model.getVerticesY(),model.getVerticesZ(),model.getFaceIndices1()[i],face.a,scale);
			put(model.getVerticesX(),model.getVerticesY(),model.getVerticesZ(),model.getFaceIndices2()[i],face.b,scale);
			put(model.getVerticesX(),model.getVerticesY(),model.getVerticesZ(),model.getFaceIndices3()[i],face.c,scale);
		}
		// A no-op scale invalidates native model bounds after direct vertex writes.
		model.scale(128, 128, 128);
		model.calculateBoundsCylinder();
	}

	private static void motionVertex(Model model,int index,EVBloatMesh.Vec original,EVBloatMesh.Vec down,int color,
		double scale,EVBloatNativeMotion.Sample motion)
	{
		double t=motion.sleep;
		double y=original.y+(down.y-original.y)*t,z=original.z+(down.z-original.z)*t;
		if(original.y < -275 && (color==EVBloatMesh.SKIN||color==EVBloatMesh.HAIR||color==EVBloatMesh.EYES||color==EVBloatMesh.BELT))
		{ y+=motion.headY*.35;z+=motion.headZ*.35; }
		else if(color==EVBloatMesh.SKIN && Math.abs(original.x)>85)
		{
			double weight=Math.max(0,Math.min(1,(original.y+260)/120));
			y+=(original.x<0?motion.leftY:motion.rightY)*weight;
			z+=(original.x<0?motion.leftZ:motion.rightZ)*weight;
		}
		model.getVerticesX()[index]=(float)((original.x+(down.x-original.x)*t)*scale);
		model.getVerticesY()[index]=(float)(y*scale);
		model.getVerticesZ()[index]=(float)(z*scale);
	}

	/** Read the unanimated body asset, excluding actor spot effects and current sleep/walk motion. */
	int bodyFaceCount(NPC npc)
	{
		NPCComposition composition = npc.getTransformedComposition();
		if (composition == null) { composition = npc.getComposition(); }
		if (composition == null) { return 0; }
		int[] ids = composition.getModels();
		if (npc.getModelOverrides() != null && npc.getModelOverrides().getModelIds() != null)
		{
			ids = npc.getModelOverrides().getModelIds();
		}
		if (ids == null || ids.length == 0) { return 0; }
		int count = 0;
		for (int id : ids)
		{
			if (id < 0) { continue; }
			ModelData body = client.loadModelData(id);
			if (body == null || body.getFaceCount() <= 0) { return 0; }
			count += body.getFaceCount();
		}
		return count;
	}

	Double scaleFor(NPC npc)
	{
		NPCComposition composition = npc.getTransformedComposition();
		if (composition == null) { composition = npc.getComposition(); }
		if (composition == null) { return null; }
		int[] ids = composition.getModels();
		if (npc.getModelOverrides() != null && npc.getModelOverrides().getModelIds() != null)
		{
			ids = npc.getModelOverrides().getModelIds();
		}
		if (ids == null || ids.length == 0) { return null; }
		double minY = 0;
		for (int id : ids)
		{
			if (id < 0) { continue; }
			ModelData body = client.loadModelData(id);
			if (body == null) { return null; }
			for (float y : body.getVerticesY())
			{
				if (!Float.isFinite(y)) { return null; }
				minY = Math.min(minY, y);
			}
		}
		int heightScale = composition.getHeightScale();
		double height = -minY * (heightScale > 0 ? heightScale : 128) / 128.0;
		if (height < 32 || height > BASE_HEIGHT * 8) { return null; }
		return height / BASE_HEIGHT;
	}

	private static double baseHeight()
	{
		double minY = 0;
		for (EVBloatMesh.Triangle face : POSES[0][0].getFaces())
		{
			minY = Math.min(minY, Math.min(face.a.y, Math.min(face.b.y, face.c.y)));
		}
		return -minY;
	}

	// 0: idle, 1: walk, 2: villager sleep, 3: planted-foot slouch. Same topology.
	private static EVBloatMesh[][] makePoses()
	{
		EVBloatMesh[][] poses = new EVBloatMesh[4][FRAME_COUNT];
		for (int mode = 0; mode < poses.length; mode++)
		{
			for (int i = 0; i < FRAME_COUNT; i++)
			{
				poses[mode][i] = EVBloatMesh.pose(i * Math.PI * 2 / FRAME_COUNT, mode == 1, mode >= 2, mode == 3);
			}
		}
		return poses;
	}

	private static void writeVertices(float[] x, float[] y, float[] z,
		int[] a, int[] b, int[] c, EVBloatMesh pose, double scale)
	{
		List<EVBloatMesh.Triangle> faces = pose.getFaces();
		for (int i = 0; i < faces.size(); i++)
		{
			EVBloatMesh.Triangle face = faces.get(i);
			put(x, y, z, a[i], face.a, scale);
			put(x, y, z, b[i], face.b, scale);
			put(x, y, z, c[i], face.c, scale);
		}
	}

	private static void put(float[] x, float[] y, float[] z, int i, EVBloatMesh.Vec v, double scale)
	{
		x[i] = (float) (v.x * scale);
		y[i] = (float) (v.y * scale);
		z[i] = (float) (v.z * scale);
	}

	void clear()
	{
		template = null;
	}
}

package com.evbloat;

import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;

/** Samples the current native deformation. No elapsed fight time or predicted events. */
final class EVBloatNativeMotion
{
	private Reference reference;
	private int npcId = -1;

	Sample sample(Client client, NPC npc)
	{
		try
		{
			if (reference == null || npcId != npc.getId())
			{
				NPCComposition c = npc.getTransformedComposition();
				if (c == null) { c = npc.getComposition(); }
				if (c == null) { return null; }
				int[] ids = c.getModels();
				if (npc.getModelOverrides() != null) { return null; }
				if (ids == null || ids.length == 0) { return null; }
				ModelData[] parts = new ModelData[ids.length];
				for (int i=0;i<ids.length;i++)
				{
					if (ids[i] < 0 || (parts[i] = client.loadModelData(ids[i])) == null) { return null; }
				}
				ModelData body = parts.length == 1 ? parts[0] : client.mergeModels(parts);
				reference = Reference.from(body, c.getWidthScale(), c.getHeightScale());
				npcId = npc.getId();
			}
			return reference == null ? null : reference.sample(npc.getModel());
		}
		catch (RuntimeException ex) { return null; } // Missing/changed geometry retains the authored pose.
	}

	static final class Sample
	{
		final double sleep, headY, headZ, leftY, leftZ, rightY, rightZ;
		Sample(double sleep, double headY, double headZ, double leftY, double leftZ, double rightY, double rightZ)
		{
			this.sleep=sleep; this.headY=headY; this.headZ=headZ;
			this.leftY=leftY; this.leftZ=leftZ; this.rightY=rightY; this.rightZ=rightZ;
		}
	}

	static final class Reference
	{
		final int[] a,b,c,region;
		final double[] y,z;
		final double height;
		Reference(int[] a,int[] b,int[] c,int[] region,double[] y,double[] z,double height)
		{ this.a=a;this.b=b;this.c=c;this.region=region;this.y=y;this.z=z;this.height=height; }

		static Reference from(ModelData model, int widthScale, int heightScale)
		{
			if (model == null || model.getVerticesCount() < 4 || model.getFaceCount() <= 0) { return null; }
			float[] vx=model.getVerticesX(),vy=model.getVerticesY(),vz=model.getVerticesZ();
			if(vx==null||vy==null||vz==null) { return null; }
			double ys=(heightScale>0?heightScale:128)/128.0,zs=(widthScale>0?widthScale:128)/128.0;
			double height=0,width=0;
			for(int i=0;i<model.getVerticesCount();i++)
			{
				if(!Float.isFinite(vx[i])||!Float.isFinite(vy[i])||!Float.isFinite(vz[i])) { return null; }
				height=Math.max(height,-vy[i]*ys);width=Math.max(width,Math.abs(vx[i]));
			}
			if(height<32||width<1) { return null; }
			int n=model.getVerticesCount();int[] regions=new int[n];double[] y=new double[n],z=new double[n];
			for(int i=0;i<n;i++)
			{
				y[i]=vy[i]*ys;z[i]=vz[i]*zs;
				if(-y[i]>height*.80) { regions[i]=1; }
				else if(Math.abs(vx[i])>width*.60 && -y[i]>height*.20 && -y[i]<height*.80)
				{ regions[i]=vx[i]<0?2:3; }
			}
			return new Reference(model.getFaceIndices1().clone(),model.getFaceIndices2().clone(),model.getFaceIndices3().clone(),regions,y,z,height);
		}

		Sample sample(Model model)
		{
			if(model==null||model.getVerticesCount()<region.length||model.getFaceCount()<a.length) { return null; }
			// Combined spot effects may append geometry. Never assume that reordered body vertices match.
			int[] ma=model.getFaceIndices1(),mb=model.getFaceIndices2(),mc=model.getFaceIndices3();
			for(int i=0;i<a.length;i++) { if(a[i]!=ma[i]||b[i]!=mb[i]||c[i]!=mc[i]) { return null; } }
			float[] my=model.getVerticesY(),mz=model.getVerticesZ();
			double[] dy=new double[4],dz=new double[4];int[] count=new int[4];
			for(int i=0;i<region.length;i++)
			{
				if(!Float.isFinite(my[i])||!Float.isFinite(mz[i])) { return null; }
				int r=region[i];if(r==0) { continue; }
				dy[r]+=my[i]-y[i];dz[r]+=mz[i]-z[i];count[r]++;
			}
			if(count[1]==0) { return null; }
			for(int i=1;i<=3;i++) { if(count[i]>0) { dy[i]/=count[i];dz[i]/=count[i]; } }
			// Blend according to observed head lowering/forward movement, never a fight clock.
			double sleep=Math.max(0,Math.min(1,Math.max(dy[1],-dz[1])/(height*.08)));
			double unit=EVBloatModelFactory.BASE_HEIGHT/height;
			return new Sample(sleep,clamp(dy[1]*unit),clamp(dz[1]*unit),clamp(dy[2]*unit),clamp(dz[2]*unit),clamp(dy[3]*unit),clamp(dz[3]*unit));
		}
		private static double clamp(double v) { return Math.max(-100,Math.min(100,v)); }
	}
}

package com.evbloat;

import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.RuneLiteObject;

/** Model requests only return artwork; the real NPC retains native scene targeting. */
final class EVBloatObject extends RuneLiteObject
{
	private volatile boolean modelRequested;
	private volatile int bodyFaceCount;

	boolean hasModelRequest() { return modelRequested; }

	void setBodyFaceCount(int count) { bodyFaceCount = count; }

	boolean isBodyModel(Model model)
	{
		return model != null && bodyFaceCount > 0 && model.getFaceCount() == bodyFaceCount;
	}

	EVBloatObject(Client client)
	{
		super(client);
	}

	@Override
	public Model getModel()
	{
		Model model = super.getModel();
		modelRequested = model != null && model.getFaceCount() > 0;
		return model;
	}

}

package com.evbloat;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.RuneLiteObject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/** Independent native NPC and artwork silhouettes, without changing either NPC or picking. */
class EVBloatOutlineOverlay extends Overlay
{
	private final Client client;
	private final EVBloatPlugin plugin;
	private final EVBloatConfig config;
	private final ModelOutlineRenderer outlines;

	@Inject
	EVBloatOutlineOverlay(Client client, EVBloatPlugin plugin, EVBloatConfig config, ModelOutlineRenderer outlines)
	{
		super(plugin);
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.outlines = outlines;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if ((!config.outline() && !config.outlineRegularBloat()) || !client.isGpu() || client.getDrawCallbacks() == null)
		{
			return null;
		}
		if (config.outlineRegularBloat())
		{
			for (NPC npc : plugin.originalOutlineNpcs())
			{
				if (BloatIds.matches(npc.getId())) { outlines.drawOutline(npc, 2, config.regularBloatOutlineColor(), 0); }
			}
		}
		if (config.outline() && !config.keepOriginals())
		{
			for (RuneLiteObject object : plugin.outlineObjects())
			{
				if (object.isActive()) { outlines.drawOutline(object, 2, config.outlineColor(), 0); }
			}
		}
		return null;
	}
}

package com.evbloat;

import com.google.inject.Provides;
import java.util.IdentityHashMap;
import java.util.Iterator;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Model;
import net.runelite.api.NPC;
import net.runelite.api.MenuEntry;
import net.runelite.api.hooks.DrawCallbacks;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.MenuEntryAdded;
import java.util.Collections;
import java.util.Collection;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.Renderable;
import net.runelite.api.WorldView;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.GameStateChanged;
