import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(name = "EV Bloat",
	description = "An oversized green EVScape-inspired character in place of Theatre of Blood Bloat",
	tags = {"tob", "bloat", "evscape", "cosmetic"})
public class EVBloatPlugin extends Plugin implements RenderCallback
{
	private static final Logger log = LoggerFactory.getLogger(EVBloatPlugin.class);
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private EVBloatConfig config;
	@Inject private RenderCallbackManager renderCallbacks;
	@Inject private EVBloatModelFactory modelFactory;
	@Inject private EVBloatGait gait;
	@Inject private OverlayManager overlayManager;
	@Inject private EVBloatOutlineOverlay outlineOverlay;
	private EVBloatDrawCallbacks drawCallbacks;
	private volatile boolean keepOriginals;
	private volatile Map<NPC, EVBloatObject> visibleReplacements = Collections.emptyMap();
	private final Map<NPC, Replacement> replacements = new IdentityHashMap<>();
	private volatile boolean running;
	private boolean modelFailure;
	private int ticks;

	@Provides
	EVBloatConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(EVBloatConfig.class);
	}

	@Override
	protected void startUp()
	{
		running = true;
		clientThread.invoke(() ->
		{
			if (running)
			{
				modelFailure = false;
				ticks = 0;
			}
		});
		renderCallbacks.register(this);
		overlayManager.add(outlineOverlay);
		// PostClientTick seeds NPCs already loaded when enabled and retries pending assets.
	}

	@Override
	protected void shutDown()
	{
		running = false;
		renderCallbacks.unregister(this);
		overlayManager.remove(outlineOverlay);
		clientThread.invoke(() ->
		{
			releaseDrawCallbacks();
			drawCallbacks = null;
			clear();
			modelFactory.clear();
		});
	}

	@Override
	public boolean addEntity(Renderable renderable, boolean ui)
	{
		// The real NPC must stay in the scene for native mouse picking and menus.
		return true;
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		if (!running) { return; }
		keepOriginals = config.keepOriginals();
		DrawCallbacks current = client.getDrawCallbacks();
		if (current == null || !client.isGpu())
		{
			releaseDrawCallbacks();
			drawCallbacks = null;
			clear();
			ticks = 0;
			return;
		}
		if (current == drawCallbacks) { return; }
		if (drawCallbacks == null || current != drawCallbacks.delegate())
		{
			drawCallbacks = new EVBloatDrawCallbacks(client, current, this::concealOriginal,
				this::concealOriginal, this::releaseDrawCallbacks);
			log.info("EV Bloat visual filter attached to {}", current.getClass().getSimpleName());
		}
		client.setDrawCallbacks(drawCallbacks);
	}

	private void releaseDrawCallbacks()
	{
		if (drawCallbacks != null && client.getDrawCallbacks() == drawCallbacks)
		{
			// A renderer with GPU disabled is stopped: never resurrect that delegate.
			client.setDrawCallbacks(client.isGpu() ? drawCallbacks.delegate() : null);
		}
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!running || !config.renameBloat()) { return; }
		MenuEntry entry = event.getMenuEntry();
		NPC npc = entry.getNpc();
		if (npc == null || !BloatIds.matches(npc.getId())) { return; }
		String name = npc.getName();
		String target = entry.getTarget();
		if (name != null && !name.isEmpty() && target != null)
		{
			// Replace only the display name, retaining color tags, level and any
			// item/spell prefix. The action, NPC index and native clickbox stay intact.
			entry.setTarget(target.replace(name, "EVScape"));
		}
	}

	boolean concealOriginal(Renderable renderable)
	{
		if (!running || keepOriginals || !client.isGpu() || client.getDrawCallbacks() == null || !(renderable instanceof NPC)) { return false; }
		EVBloatObject object = visibleReplacements.get(renderable);
		return object != null && object.hasModelRequest();
	}

	boolean concealOriginal(Renderable renderable, Model model)
	{
		if (!running || keepOriginals || !client.isGpu() || client.getDrawCallbacks() == null
			|| !(renderable instanceof NPC)) { return false; }
		EVBloatObject object = visibleReplacements.get(renderable);
		// Actor effects can reach the zone hooks with Bloat as their owner. Hide
		// only the base body's face count; forward flies and other effect models.
		// Unknown or combined body/effect geometry stays visible (fail open).
		return object != null && object.hasModelRequest() && object.isBodyModel(model);
	}

	Collection<? extends RuneLiteObject> outlineObjects()
	{
		return visibleReplacements.values();
	}

	Collection<NPC> originalOutlineNpcs()
	{
		// Snapshot contains only native NPCs with active replacement objects.
		return visibleReplacements.keySet();
	}

	private void publishReplacements()
	{
		Map<NPC, EVBloatObject> snapshot = new IdentityHashMap<>();
		for (Map.Entry<NPC, Replacement> entry : replacements.entrySet())
		{
			if (entry.getValue().object.isActive()) { snapshot.put(entry.getKey(), entry.getValue().object); }
		}
		visibleReplacements = Collections.unmodifiableMap(snapshot);
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		track(event.getNpc());
	}

	@Subscribe
	public void onNpcChanged(NpcChanged event)
	{
		NPC npc = event.getNpc();
		if (BloatIds.matches(npc.getId()))
		{
			track(npc);
		}
		else
		{
			remove(npc);
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		remove(event.getNpc());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			clear(); // Loading, hopping and logout cannot leave old scene objects behind.
		}
	}

	@Subscribe
	public void onPostClientTick(PostClientTick event)
	{
		if (!running || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		WorldView view = client.getTopLevelWorldView();
		if (view == null) { clear(); return; }
		if (!client.isGpu() || client.getDrawCallbacks() == null)
		{
			releaseDrawCallbacks();
			drawCallbacks = null;
			clear();
			ticks = 0;
			return;
		}
		ticks++;
		// Scan twice a second for enable-mid-fight and cache download retries.
		if (ticks == 1 || ticks % 25 == 0)
		{
			for (NPC npc : view.npcs())
			{
				track(npc);
			}
		}
		Iterator<Map.Entry<NPC, Replacement>> iterator = replacements.entrySet().iterator();
		while (iterator.hasNext())
		{
			Map.Entry<NPC, Replacement> entry = iterator.next();
			NPC npc = entry.getKey();
			Replacement replacement = entry.getValue();
			LocalPoint point = npc.getLocalLocation();
			if (!BloatIds.matches(npc.getId()) || point == null ||
				point.getWorldView() != view.getId())
			{
				replacement.object.setActive(false);
				iterator.remove();
				continue;
			}
			replacement.object.setLocation(point, view.getPlane());
			replacement.object.setOrientation(npc.getCurrentOrientation() & 2047);
			int mode = mode(npc, replacement, point);
			if (mode == 2 && config.originalBloatSlouch()) { mode = 3; }
			if (ticks % 25 == 0 || replacement.bodyNpcId != npc.getId())
			{
				replacement.object.setBodyFaceCount(modelFactory.bodyFaceCount(npc));
				replacement.bodyNpcId = npc.getId();
			}
			EVBloatNativeMotion.Sample nativeMotion = null;
			if (mode != 1 && npc.getAnimation() != AnimationID.TOB_BLOAT_DEATH)
			{ nativeMotion = replacement.nativeMotion.sample(client, npc); }
			boolean resized = false;
			if (replacement.sizedNpcId != npc.getId()) { replacement.sizeFitted = false; }
			if (!replacement.sizeFitted && ticks % 25 == 0)
			{
				Double scale = modelFactory.scaleFor(npc);
				if (scale != null)
				{
					replacement.scale = scale;
					replacement.sizeFitted = true;
					replacement.sizedNpcId = npc.getId();
					resized = true;
				}
			}
			int flyFrame = EVBloatModelFactory.frame(ticks * 0.02, replacement.phase);
			int frame = EVBloatModelFactory.frame(ticks * 0.02, replacement.phase);
			if (mode == 1) { frame = gait.frame(npc, frame); }
			if (mode == 3) { frame = gait.slouchFrame(npc); }
			replacement.previousPoint = point;
			int sizePercent = sizePercent();
			if (nativeMotion != null || replacement.hadNativeMotion || resized || sizePercent != replacement.lastSizePercent || frame != replacement.lastFrame || flyFrame != replacement.lastFlyFrame || mode != replacement.lastMode)
			{
				double scale = replacement.scale * sizePercent / 100.0;
				EVBloatModelFactory.animate(replacement.model, mode, frame, scale, flyFrame, nativeMotion, config.originalBloatSlouch());
				replacement.hadNativeMotion = nativeMotion != null;
				replacement.object.setRadius((int) Math.ceil(180 * Math.max(1, scale)));
				replacement.lastSizePercent = sizePercent;
				replacement.lastFrame = frame;
				replacement.lastFlyFrame = flyFrame;
				replacement.lastMode = mode;
			}
			if (!replacement.object.isActive())
			{
				replacement.object.setActive(true);
			}
		}
		publishReplacements();
	}

	private void track(NPC npc)
	{
		if (!running || modelFailure || !client.isGpu() || client.getDrawCallbacks() == null || client.getGameState() != GameState.LOGGED_IN ||
			!BloatIds.matches(npc.getId()) || replacements.containsKey(npc))
		{
			return;
		}
		WorldView view = client.getTopLevelWorldView();
		if (view == null) { return; }
		LocalPoint point = npc.getLocalLocation();
		if (point == null || point.getWorldView() != view.getId())
		{
			return;
		}
		try
		{
			// Cosmetic loop phase from the location; never predicts a combat event.
			int seed = point.getSceneX() * 31 + point.getSceneY();
			int phase = Math.floorMod(seed, EVBloatModelFactory.FRAME_COUNT);
			Double fittedScale = modelFactory.scaleFor(npc);
			double scale = fittedScale == null ? 1 : fittedScale;
			double renderedScale = scale * sizePercent() / 100.0;
			Model model = modelFactory.create(0, phase, renderedScale);
			if (model == null)
			{
				return;
			}
			EVBloatObject object = new EVBloatObject(client);
			object.setModel(model);
			object.setBodyFaceCount(modelFactory.bodyFaceCount(npc));
			object.setLocation(point, view.getPlane());
			object.setOrientation(npc.getCurrentOrientation() & 2047);
			object.setRenderMode(Renderable.RENDERMODE_SORTED);
			object.setRadius((int) Math.ceil(180 * Math.max(1, renderedScale)));
			object.setActive(true);
			replacements.put(npc, new Replacement(object, model, phase, scale, fittedScale != null, npc.getId()));
			publishReplacements();
			log.info("EV Bloat replacement registered: NPC {}, vertices {}, faces {}",
				npc.getId(), model.getVerticesCount(), model.getFaceCount());
		}
		catch (RuntimeException ex)
		{
			modelFailure = true;
			clear();
			log.warn("EV Bloat model creation failed; keeping original Bloat visible. Re-enable to retry.", ex);
		}
	}

	private static int mode(NPC npc, Replacement replacement, LocalPoint point)
	{
		int animation = npc.getAnimation();
		if (animation == AnimationID.TOB_BLOAT_SLEEP || animation == AnimationID.TOB_BLOAT_DEATH
			|| animation == AnimationID.TOB_BLOAT_STUNNED_SHORT) { return 2; }
		if (animation == AnimationID.TOB_BLOAT_WALK || EVBloatGait.isWalkPose(npc)
			|| (replacement.previousPoint != null && !point.equals(replacement.previousPoint))) { return 1; }
		return 0;
	}

	private void remove(NPC npc)
	{
		Replacement replacement = replacements.remove(npc);
		if (replacement != null)
		{
			replacement.object.setActive(false);
		}
		publishReplacements();
	}

	private void clear()
	{
		for (Replacement replacement : replacements.values())
		{
			replacement.object.setActive(false);
		}
		replacements.clear();
		visibleReplacements = Collections.emptyMap();
	}

	private int sizePercent()
	{
		return 89;
	}

	private static final class Replacement
	{
		private final EVBloatObject object;
		private final Model model;
		private final int phase;
		private int lastFrame;
		private int lastFlyFrame = -1;
		private final EVBloatNativeMotion nativeMotion = new EVBloatNativeMotion();
		private boolean hadNativeMotion;
		private int lastMode;
		private int lastSizePercent = -1;
		private LocalPoint previousPoint;
		private double scale;
		private boolean sizeFitted;
		private int sizedNpcId;
		private int bodyNpcId;

		private Replacement(EVBloatObject object, Model model, int phase, double scale, boolean sizeFitted, int npcId)
		{
			this.object = object;
			this.model = model;
			this.phase = phase;
			this.lastFrame = phase;
			this.scale = scale;
			this.sizeFitted = sizeFitted;
			this.sizedNpcId = npcId;
			this.bodyNpcId = npcId;
		}
	}
}

package com.evbloat;

import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.util.Arrays;
import java.util.Collections;
import net.runelite.api.*;
import net.runelite.api.hooks.DrawCallbacks;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class EVBloatDrawCallbacksTest
{
	@Test
	public void zoneTempFilteringDoesNotAlterTheNativeModelOrPickingState()
	{
		Client client = mock(Client.class);
		DrawCallbacks renderer = mock(DrawCallbacks.class);
		NPC npc = mock(NPC.class);
		Model nativeModel = mock(Model.class);
		GameObject object = mock(GameObject.class);
		when(object.getRenderable()).thenReturn(npc);
		DrawCallbacks filter = new EVBloatDrawCallbacks(client,renderer,r -> r == npc);
		filter.drawTemp(null,null,object,nativeModel,7,11,12,13);
		filter.drawDynamic(-1,null,null,null,npc,nativeModel,7,11,12,13);
		filter.drawDynamic(null,null,null,npc,nativeModel,7,11,12,13);
		verifyNoInteractions(client,nativeModel,renderer); // Scene performs native picking next.
	}

	@Test
	public void legacyPickingUsesTheOriginalTagProjectionAndModelAtTheDrawCall()
	{
		Client client = mock(Client.class);
		DrawCallbacks renderer = mock(DrawCallbacks.class);
		NPC npc = mock(NPC.class);
		Model nativeModel = mock(Model.class);
		Projection projection = mock(Projection.class);
		when(npc.getModel()).thenReturn(nativeModel);
		when(nativeModel.getModelHeight()).thenReturn(200);
		DrawCallbacks filter = new EVBloatDrawCallbacks(client,renderer,r -> r == npc);
		filter.draw(projection,null,npc,123,11,12,13,0xabc123L);
		verify(client).checkClickbox(projection,nativeModel,123,11,12,13,0xabc123L);
		verify(npc).setModelHeight(200);
		verifyNoInteractions(renderer);
	}

	@Test
	public void legacyFailureForwardsTheNativeDraw()
	{
		Client client = mock(Client.class);
		DrawCallbacks renderer = mock(DrawCallbacks.class);
		NPC npc = mock(NPC.class);
		Model nativeModel = mock(Model.class);
		when(npc.getModel()).thenReturn(nativeModel);
		doThrow(new IllegalStateException()).when(client).checkClickbox(null,nativeModel,0,1,2,3,4);
		new EVBloatDrawCallbacks(client,renderer,r -> r == npc).draw(null,null,npc,0,1,2,3,4);
		verify(renderer).draw(null,null,npc,0,1,2,3,4);
	}

	@Test
	public void everyUnfilteredRendererHookForwardsItsArgumentsAndResult() throws Exception
	{
		Client client = mock(Client.class);
		for (Method method : DrawCallbacks.class.getDeclaredMethods())
		{
			if (Modifier.isStatic(method.getModifiers())) { continue; }
			DrawCallbacks renderer = mock(DrawCallbacks.class, invocation ->
				invocation.getMethod().getReturnType() == boolean.class ? true : null);
			EVBloatDrawCallbacks filter = new EVBloatDrawCallbacks(client,renderer,r -> false);
			Object[] args = new Object[method.getParameterCount()];
			Class<?>[] types = method.getParameterTypes();
			for (int i=0;i<types.length;i++)
			{
				Class<?> t=types[i];
				args[i]=t==int.class ? (Object)(i+10) : t==long.class ? (Object)1234L : t==float.class ? (Object)(i+0.25f)
					: t==double.class ? (Object)(i+0.5) : t==java.util.Set.class ? Collections.singleton(7) : mock(t);
			}
			Object result=method.invoke(filter,args);
			if (method.getReturnType()==boolean.class) { assertEquals(true,result); }
			assertEquals(method.toString(),1,mockingDetails(renderer).getInvocations().size());
			org.mockito.invocation.Invocation invocation=mockingDetails(renderer).getInvocations().iterator().next();
			assertEquals(method,invocation.getMethod());
			assertTrue(Arrays.equals(args,invocation.getArguments()));
		}
		verifyNoInteractions(client);
	}
}

