package com.evbloat;

import org.junit.Test;
import static org.junit.Assert.*;

public class EVBloatMeshTest
{
	@Test
	public void sleepingSlumpsForwardWithBothFeetPlantedInsteadOfRollingOntoTheBack()
	{
		double top=0, front=0;
		for (EVBloatMesh.Triangle t : EVBloatMesh.pose(0,false,true).getFaces())
		{
			for (EVBloatMesh.Vec v : new EVBloatMesh.Vec[]{t.a,t.b,t.c})
			{
				top=Math.min(top,v.y);
				if (t.color==EVBloatMesh.SKIN) { front=Math.min(front,v.z); }
				if (t.color==EVBloatMesh.BOOTS) { assertTrue(v.y <= -2 && v.y >= -38); }
			}
		}
		assertTrue("Sleep remains upright rather than flat",top < -250);
		assertTrue("Head slumps toward the front",front < -140);
	}
	@Test
	public void allPosesHaveStableTopologyAndFiniteNonDegenerateTriangles()
	{
		int faces = EVBloatMesh.pose(0, false, false).getFaces().size();
		for (int mode = 0; mode < 4; mode++)
		{
			for (int frame = 0; frame < 32; frame++)
			{
				EVBloatMesh mesh = EVBloatMesh.pose(frame * Math.PI * 2 / 32, mode == 1, mode >= 2, mode == 3);
				assertEquals(faces, mesh.getFaces().size());
				for (EVBloatMesh.Triangle t : mesh.getFaces())
				{
					assertTrue(t.color >= 0 && t.color < 8);
					for (EVBloatMesh.Vec v : new EVBloatMesh.Vec[]{t.a, t.b, t.c})
					{
						assertTrue(Double.isFinite(v.x) && Double.isFinite(v.y) && Double.isFinite(v.z));
					}
					double ax=t.b.x-t.a.x, ay=t.b.y-t.a.y, az=t.b.z-t.a.z;
					double bx=t.c.x-t.a.x, by=t.c.y-t.a.y, bz=t.c.z-t.a.z;
					double nx=ay*bz-az*by, ny=az*bx-ax*bz, nz=ax*by-ay*bx;
					assertTrue(nx*nx+ny*ny+nz*nz > 0.0001);
				}
			}
		}
	}

	@Test
	public void slouchLowersTheBeltWithoutCollapsingTheBoots()
	{
		double oldBelt = 0, newBelt = 0;
		int beltVertices = 0;
		java.util.List<EVBloatMesh.Triangle> old = EVBloatMesh.pose(0,false,true).getFaces();
		java.util.List<EVBloatMesh.Triangle> lower = EVBloatMesh.pose(0,false,true,true).getFaces();
		for (int i=0;i<old.size();i++)
		{
			EVBloatMesh.Triangle t = old.get(i), n = lower.get(i);
			if (t.color == EVBloatMesh.BELT && t.a.y > -150)
			{
				oldBelt += t.a.y + t.b.y + t.c.y;
				newBelt += n.a.y + n.b.y + n.c.y;
				beltVertices += 3;
			}
		}
		for (EVBloatMesh.Triangle t : EVBloatMesh.pose(0,false,true,true).getFaces())
		{
			for (EVBloatMesh.Vec v : new EVBloatMesh.Vec[]{t.a,t.b,t.c})
			{
				assertTrue("Slouch stays above the floor",v.y <= 0);
				if (t.color == EVBloatMesh.BOOTS) { assertTrue(v.y >= -38 && v.y <= -2); }
			}
		}
		assertTrue("Hip level drops",newBelt/beltVertices > oldBelt/beltVertices + 10);
	}

	@Test
	public void optionalSlouchKeepsEveryBootVertexIdenticalToDefaultAtEveryFrame()
	{
		for (int frame=0;frame<32;frame++)
		{
			double phase=frame*Math.PI*2/32;
			java.util.List<EVBloatMesh.Triangle> normal=EVBloatMesh.pose(phase,false,true).getFaces();
			java.util.List<EVBloatMesh.Triangle> slouch=EVBloatMesh.pose(phase,false,true,true).getFaces();
			for (int i=0;i<normal.size();i++)
			{
				if (normal.get(i).color!=EVBloatMesh.BOOTS) { continue; }
				EVBloatMesh.Triangle a=normal.get(i),b=slouch.get(i);
				EVBloatMesh.Vec[] av={a.a,a.b,a.c},bv={b.a,b.b,b.c};
				for(int j=0;j<3;j++)
				{
					assertEquals(av[j].x,bv[j].x,0);
					assertEquals(av[j].y,bv[j].y,0);
					assertEquals(av[j].z,bv[j].z,0);
				}
			}
		}
	}

	@Test
	public void cosmeticSwarmMovesOutsideBodyAndStaysWithinNativeBufferLimits()
	{
		java.util.List<EVBloatMesh.Triangle> a=EVBloatMesh.pose(0,false,false).getFaces();
		java.util.List<EVBloatMesh.Triangle> b=EVBloatMesh.pose(1,false,false).getFaces();
		assertTrue(a.size()*3<6500);
		assertTrue(a.size()<=EVBloatModelFactory.MAX_FACES);
		int first=a.size()-EVBloatMesh.SWARM_FACES;
		assertNotEquals(a.get(first).a.x,b.get(first).a.x,0.001);
		for(int i=first;i<a.size();i++)
		{
			for(EVBloatMesh.Vec v:new EVBloatMesh.Vec[]{a.get(i).a,a.get(i).b,a.get(i).c})
			{
				assertTrue(Math.hypot(v.x,v.z)>140);
				assertTrue(v.y<0);
			}
		}
	}

	@Test
	public void nativeInspiredSlouchKeepsTorsoUprightAndBowsHeadIndependently()
	{
		java.util.List<EVBloatMesh.Triangle> a=EVBloatMesh.pose(0,false,false).getFaces();
		java.util.List<EVBloatMesh.Triangle> b=EVBloatMesh.pose(0,false,true,true).getFaces();
		double oldShirtTop=0,newShirtTop=0,faceTravel=0;
		for(int i=0;i<a.size()-EVBloatMesh.SWARM_FACES;i++)
		{
			EVBloatMesh.Triangle src=a.get(i),dst=b.get(i);
			if(src.color==EVBloatMesh.SHIRT)
			{
				oldShirtTop=Math.min(oldShirtTop,src.a.y);
				newShirtTop=Math.min(newShirtTop,dst.a.y);
			}
			if(src.color==EVBloatMesh.EYES) { faceTravel=Math.max(faceTravel,Math.abs(dst.a.z-src.a.z)); }
		}
		assertTrue("Upper torso stays tall instead of folding over",newShirtTop<oldShirtTop+40);
		assertTrue("Head droops forward from its own neck hinge",faceTravel>30);
	}

	@Test
	public void animationFrameWrapsInBothDirections()
	{
		for (int i = -100; i < 100; i++)
		{
			int frame = EVBloatModelFactory.frame(i * 0.1, i);
			assertTrue(frame >= 0 && frame < EVBloatModelFactory.FRAME_COUNT);
		}
	}

	@Test
	public void walkingLiftsOneFootAndKeepsTheOtherOnTheGround()
	{
		boolean leftLifted = false, rightLifted = false;
		for (int frame = 0; frame < 32; frame++)
		{
			double leftSole = Double.NEGATIVE_INFINITY, rightSole = Double.NEGATIVE_INFINITY;
			for (EVBloatMesh.Triangle t : EVBloatMesh.pose(frame * Math.PI * 2 / 32, true, false).getFaces())
			{
				if (t.color != EVBloatMesh.BOOTS) { continue; }
				for (EVBloatMesh.Vec v : new EVBloatMesh.Vec[]{t.a,t.b,t.c})
				{
					if (v.x < 0) { leftSole = Math.max(leftSole,v.y); }
					else { rightSole = Math.max(rightSole,v.y); }
				}
			}
			assertEquals(-2, Math.max(leftSole,rightSole), 0.001);
			assertTrue(leftSole <= -2.001 || rightSole <= -2.001 || Math.abs(leftSole-rightSole) < 0.001);
			leftLifted |= leftSole < -20;
			rightLifted |= rightSole < -20;
		}
		assertTrue(leftLifted && rightLifted);
	}
}

package com.evbloat;

import net.runelite.api.Model;
import net.runelite.api.ModelData;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class EVBloatNativeMotionTest
{
	private ModelData reference()
	{
		ModelData d=mock(ModelData.class);
		when(d.getVerticesCount()).thenReturn(6);when(d.getFaceCount()).thenReturn(2);
		when(d.getVerticesX()).thenReturn(new float[]{0,10,-100,100,0,0});
		when(d.getVerticesY()).thenReturn(new float[]{-400,-360,-160,-160,-100,0});
		when(d.getVerticesZ()).thenReturn(new float[]{0,-20,0,0,0,0});
		when(d.getFaceIndices1()).thenReturn(new int[]{0,2});
		when(d.getFaceIndices2()).thenReturn(new int[]{1,3});
		when(d.getFaceIndices3()).thenReturn(new int[]{4,5});
		return d;
	}
	private Model model(float drop,float forward)
	{
		Model m=mock(Model.class);when(m.getVerticesCount()).thenReturn(6);when(m.getFaceCount()).thenReturn(2);
		when(m.getVerticesY()).thenReturn(new float[]{-400+drop,-360+drop,-160,-160,-100,0});
		when(m.getVerticesZ()).thenReturn(new float[]{forward,-20+forward,0,0,0,0});
		when(m.getFaceIndices1()).thenReturn(new int[]{0,2});when(m.getFaceIndices2()).thenReturn(new int[]{1,3});when(m.getFaceIndices3()).thenReturn(new int[]{4,5});return m;
	}
	@Test public void loweringAndLiftingFollowCurrentNativeGeometryWithoutAClock()
	{
		EVBloatNativeMotion.Reference r=EVBloatNativeMotion.Reference.from(reference(),128,128);
		assertEquals(0,r.sample(model(0,0)).sleep,0);
		double half=r.sample(model(16,-16)).sleep;
		assertEquals(.5,half,0);
		assertEquals(1,r.sample(model(32,-32)).sleep,0);
		assertEquals(half,r.sample(model(16,-16)).sleep,0);
		assertEquals(0,r.sample(model(0,0)).sleep,0);
	}
	@Test public void repeatingHeldFrameIsStableAndDoesNotMutateNativeArrays()
	{
		ModelData d=reference();Model m=model(16,-16);
		float[] before=m.getVerticesY().clone(),base=d.getVerticesY().clone();
		EVBloatNativeMotion.Reference r=EVBloatNativeMotion.Reference.from(d,128,128);
		for(int i=0;i<100;i++) { assertEquals(.5,r.sample(m).sleep,0); }
		assertArrayEquals(before,m.getVerticesY(),0);assertArrayEquals(base,d.getVerticesY(),0);
		verify(m,never()).scale(anyInt(),anyInt(),anyInt());
	}
	@Test public void nativeArmLiftIsTransferredIndependently()
	{
		Model m=model(0,0);m.getVerticesY()[2]-=20;m.getVerticesZ()[2]-=15;
		EVBloatNativeMotion.Sample s=EVBloatNativeMotion.Reference.from(reference(),128,128).sample(m);
		assertTrue(s.leftY<0 && s.leftZ<0);assertEquals(0,s.rightY,0);assertEquals(0,s.sleep,0);
	}
	@Test public void appendedEffectsAreAcceptedButChangedBodyTopologyFailsSafely()
	{
		EVBloatNativeMotion.Reference r=EVBloatNativeMotion.Reference.from(reference(),128,128);
		Model m=model(16,-16);when(m.getFaceCount()).thenReturn(3);
		when(m.getFaceIndices1()).thenReturn(new int[]{0,2,5});when(m.getFaceIndices2()).thenReturn(new int[]{1,3,4});when(m.getFaceIndices3()).thenReturn(new int[]{4,5,3});
		assertNotNull(r.sample(m));m.getFaceIndices1()[0]=1;assertNull(r.sample(m));
	}
	@Test public void missingNonFiniteAndShortModelsFailSafely()
	{
		EVBloatNativeMotion.Reference r=EVBloatNativeMotion.Reference.from(reference(),128,128);
		assertNull(r.sample(null));Model m=model(16,-16);m.getVerticesY()[0]=Float.NaN;assertNull(r.sample(m));
		when(m.getVerticesCount()).thenReturn(1);assertNull(r.sample(m));assertNull(EVBloatNativeMotion.Reference.from(null,128,128));
	}
	@Test public void referenceScalingDoesNotCauseFalseMotion()
	{
		ModelData d=reference();EVBloatNativeMotion.Reference r=EVBloatNativeMotion.Reference.from(d,128,160);
		Model m=model(0,0);for(int i=0;i<m.getVerticesY().length;i++) { m.getVerticesY()[i]*=1.25; }
		assertEquals(0,r.sample(m).sleep,0);assertEquals(0,r.sample(m).headY,0);
	}
	@Test public void motionBlendsTheAuthoredBodyAndKeepsBootsAndFlyGeometryFinite()
	{
		int faces=EVBloatMesh.pose(0,false,false).getFaces().size();
		Model m=mock(Model.class);float[] x=new float[faces*3],y=new float[faces*3],z=new float[faces*3];
		int[] a=new int[faces],b=new int[faces],c=new int[faces];
		for(int i=0;i<faces;i++) { a[i]=i*3;b[i]=i*3+1;c[i]=i*3+2; }
		when(m.getVerticesX()).thenReturn(x);when(m.getVerticesY()).thenReturn(y);when(m.getVerticesZ()).thenReturn(z);
		when(m.getFaceIndices1()).thenReturn(a);when(m.getFaceIndices2()).thenReturn(b);when(m.getFaceIndices3()).thenReturn(c);
		java.util.List<EVBloatMesh.Triangle> base=EVBloatMesh.pose(0,false,false).getFaces();
		for(boolean slouch:new boolean[]{false,true})
		{
			for(int step=0;step<=20;step++)
			{
				double t=step/20.0;
				EVBloatModelFactory.animate(m,slouch?3:2,0,.89,0,new EVBloatNativeMotion.Sample(t,t*20,-t*15,-t*10,0,-t*10,0),slouch);
				for(int i=0;i<x.length;i++) { assertTrue(Float.isFinite(x[i])&&Float.isFinite(y[i])&&Float.isFinite(z[i])); }
				for(int i=0;i<faces;i++)
				{
					if(base.get(i).color==EVBloatMesh.BOOTS)
					{ assertTrue(y[a[i]]<=0 && y[b[i]]<=0 && y[c[i]]<=0); }
				}
			}
		}
	}
	@Test public void animationFacingAndSizeAreAbsentFromTheSettingsInterface()
	{
		for(java.lang.reflect.Method m:EVBloatConfig.class.getMethods())
		{ assertFalse(m.getName().equals("facingOffset")||m.getName().equals("sizePercent")||m.getName().equals("animate")); }
	}

}

