	@Test
	public void uniformSizePersistsAcrossWalkSleepAndRepeatedAnimationUpdates()
	{
		Fixture f = new Fixture();
		EVBloatModelFactory factory = new EVBloatModelFactory(f.client);
		Model artwork = factory.create(0,0,2);
		for (int mode=0;mode<3;mode++)
		{
			for (int frame=0;frame<32;frame++)
			{
				Model reference = factory.create(mode,frame);
				EVBloatModelFactory.animate(artwork,mode,frame,2);
				assertTwice(reference.getVerticesX(),artwork.getVerticesX());
				assertTwice(reference.getVerticesY(),artwork.getVerticesY());
				assertTwice(reference.getVerticesZ(),artwork.getVerticesZ());
			}
		}
		EVBloatModelFactory.animate(artwork,0,0,2);
		float[] once = artwork.getVerticesY().clone();
		EVBloatModelFactory.animate(artwork,0,0,2);
		assertArrayEquals(once,artwork.getVerticesY(),0);
	}

	private static void assertTwice(float[] source,float[] scaled)
	{
		assertEquals(source.length,scaled.length);
		for (int i=0;i<source.length;i++) { assertEquals(source[i]*2,scaled[i],0.0001); }
	}

