	private static final class Fixture
	{
		private final EVBloatPlugin plugin = new EVBloatPlugin();
		private final RenderCallbackManager callbacks = new RenderCallbackManager();
		private final DrawCallbacks renderer = mock(DrawCallbacks.class);
		private DrawCallbacks currentDraw = renderer;
		private boolean gpu = true;
		private final Set<RuneLiteObjectController> active = Collections.newSetFromMap(new IdentityHashMap<>());
		private int npcId = 8359;
		private int worldViewId = -1;
		private boolean ready = true;
		private boolean keepOriginals;
		private boolean projectionReady = true;
		private boolean rejectClickbox;
		private int clickboxChecks;
		private Model checkedModel;
		private long checkedHash;
		private int npcAnimation = -1;
		private int poseAnimation = -1;
		private int nativeFrame;
		private boolean nativeModelReady = true;
		private boolean renameBloat;
		private boolean originalBloatSlouch;
		private String npcName = "Pestilent Bloat";
		private Model nativeModel = new FakeMesh(1).model();
		private final Projection projection = proxy(Projection.class, (obj, method, args) -> null);
		private GameState gameState = GameState.LOGGED_IN;
		private FakeMesh seed = new FakeMesh(1);
		private FakeMesh body = new FakeMesh(1);
		private boolean fitBody;
		private boolean bodyReady = true;
		private final NPCComposition composition = proxy(NPCComposition.class,(o,m,a) -> {
			if (m.getName().equals("getModels")) { return new int[]{999}; }
			if (m.getName().equals("getHeightScale")) { return fitBody ? 128 : 1; }
			return defaultValue(m);
		});
		private final NPC npc = proxy(NPC.class, (obj, method, args) -> {
			switch (method.getName())
			{
				case "getId": return npcId;
				case "getName": return npcName;
				case "getComposition": return composition;
				case "getIndex": return 41;
				case "getModel": return nativeModelReady ? nativeModel : null;
				case "getAnimation": return npcAnimation;
				case "getPoseAnimation": return poseAnimation;
				case "getPoseAnimationFrame":
				case "getAnimationFrame": return nativeFrame;
				case "getLocalLocation": return new LocalPoint(6400, 6400, worldViewId);
				default: return defaultValue(method);
			}
		});
		private final WorldView view = proxy(WorldView.class, (obj, method, args) -> {
			switch (method.getName())
			{
				case "getId": return -1;
				case "getCanvasProjection": return projectionReady ? projection : null;
				case "npcs": return new IndexedObjectSet<NPC>() {
					public NPC byIndex(int i) { return npc; }
					public Iterator<NPC> iterator() { return Collections.singletonList(npc).iterator(); }
				};
				default: return defaultValue(method);
			}
		});
		private final Client client = proxy(Client.class, (obj, method, args) -> {
			switch (method.getName())
			{
				case "getGameState": return gameState;
				case "checkClickbox":
					if (rejectClickbox) { throw new IllegalStateException("Renderer unavailable"); }
					clickboxChecks++;
					checkedModel = (Model) args[1];
					checkedHash = (Long) args[6];
					return null;
				case "isClientThread": return true;
				case "isGpu": return gpu;
				case "getDrawCallbacks": return currentDraw;
				case "setDrawCallbacks": currentDraw = (DrawCallbacks)args[0]; return null;
				case "getTopLevelWorldView": return view;
				case "loadModelData": return (int)args[0]==999 ? bodyReady ? body.data() : null : ready ? seed.data() : null;
				case "loadAnimation": return proxy(Animation.class, (a, m, p) -> {
					if (m.getName().equals("getNumFrames")) { return 8; }
					if (m.getName().equals("getFrameLengths")) { return new int[]{2,2,2,2,2,2,2,2}; }
					return defaultValue(m);
				});
				case "mergeModels": return new FakeMesh(((ModelData[]) args[0]).length).data();
				case "registerRuneLiteObject": active.add((RuneLiteObjectController) args[0]); return null;
				case "removeRuneLiteObject": active.remove(args[0]); return null;
				case "isRuneLiteObjectRegistered": return active.contains(args[0]);
				default: return defaultValue(method);
			}
		});

		private Fixture()
		{
			inject(plugin, "client", client);
			ClientThread clientThread = new ClientThread();
			inject(clientThread, "client", client);
			inject(plugin, "clientThread", clientThread);
			inject(plugin, "config", new EVBloatConfig() {
				@Override public boolean keepOriginals() { return keepOriginals; }
				@Override public boolean renameBloat() { return renameBloat; }
				@Override public boolean originalBloatSlouch() { return originalBloatSlouch; }
			});
			inject(plugin, "renderCallbacks", callbacks);
			inject(plugin, "modelFactory", new EVBloatModelFactory(client));
			inject(plugin, "gait", new EVBloatGait(client));
			inject(plugin, "overlayManager", mock(OverlayManager.class));
			inject(plugin, "outlineOverlay", mock(EVBloatOutlineOverlay.class));
		}

	}

	private static final class FakeMesh implements InvocationHandler
	{
		private float[] x, y, z;
		private int[] a, b, c;
		private short[] colors;
		private short[] textures;
		private byte[] alpha;

		private FakeMesh(int faces)
		{
			x = new float[faces * 3]; y = x.clone(); z = x.clone();
			a = new int[faces]; b = new int[faces]; c = new int[faces];
			colors = new short[faces];
			for (int i = 0; i < faces; i++)
			{
				a[i] = i * 3; b[i] = i * 3 + 1; c[i] = i * 3 + 2;
				x[b[i]] = 1; y[c[i]] = 1;
			}
		}

		private ModelData data() { return proxy(ModelData.class, this); }
		private Model model() { return proxy(Model.class, this); }

		@Override
		public Object invoke(Object object, Method method, Object[] args)
		{
			switch (method.getName())
			{
				case "getVerticesCount": return x.length;
				case "getFaceCount": return a.length;
				case "getVerticesX": return x;
				case "getVerticesY": return y;
				case "getVerticesZ": return z;
				case "getFaceIndices1": return a;
				case "getFaceIndices2": return b;
				case "getFaceIndices3": return c;
				case "getFaceColors": return colors;
				case "getFaceTextures": return textures;
				case "getFaceTransparencies": return alpha;
				case "shallowCopy":
					FakeMesh copy = new FakeMesh(a.length);
					copy.x = x; copy.y = y; copy.z = z;
					copy.a = a; copy.b = b; copy.c = c;
					copy.colors = colors; copy.alpha = alpha;
					copy.textures = textures;
					return copy.data();
				case "cloneVertices": x = x.clone(); y = y.clone(); z = z.clone(); return object;
				case "cloneColors": colors = colors.clone(); return object;
				case "cloneTextures": textures = textures.clone(); return object;
				case "cloneTransparencies": alpha = new byte[a.length]; return object;
				case "translate":
					for (int i = 0; i < x.length; i++) { x[i] += (int) args[0]; }
					return object;
				case "light": return proxy(Model.class, this);
				case "scale": return object;
				default: return defaultValue(method);
			}
		}
	}

	private static void inject(Object target, String fieldName, Object value)
	{
		try
		{
			Field field = target.getClass().getDeclaredField(fieldName);
			field.setAccessible(true);
			field.set(target, value);
		}
		catch (ReflectiveOperationException ex) { throw new AssertionError(ex); }
	}

	private static <T> T proxy(Class<T> type, InvocationHandler handler)
	{
		return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type}, handler));
	}

	private static Object defaultValue(Method method)
	{
		Class<?> type = method.getReturnType();
		if (type == boolean.class) { return false; }
		if (type == int.class) { return 0; }
		if (type == byte.class) { return (byte) 0; }
		if (type == long.class) { return 0L; }
		if (type == float.class) { return 0f; }
		if (type == double.class) { return 0d; }
		if (type == short.class) { return (short) 0; }
		if (type == char.class) { return '\0'; }
		return null;
	}
}

package com.evbloat;

import net.runelite.api.Client;
import net.runelite.api.ModelData;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class EVBloatScaleTest
{
	@Test
	public void fitsBodyAssetsAndNpcHeightScaleWithoutReadingTheCurrentAnimatedModel()
	{
		Client client = mock(Client.class);
		NPC npc = mock(NPC.class);
		NPCComposition composition = mock(NPCComposition.class);
		when(npc.getTransformedComposition()).thenReturn(composition);
		when(composition.getModels()).thenReturn(new int[]{10,11});
		when(composition.getHeightScale()).thenReturn(160);
		float[] y = new float[]{0,-512,-200};
		ModelData body = mock(ModelData.class), other = mock(ModelData.class);
		when(body.getVerticesY()).thenReturn(y);
		when(other.getVerticesY()).thenReturn(new float[]{-400,0});
		when(client.loadModelData(10)).thenReturn(body);
		when(client.loadModelData(11)).thenReturn(other);
		assertEquals(640 / EVBloatModelFactory.BASE_HEIGHT,new EVBloatModelFactory(client).scaleFor(npc),0.000001);
		assertArrayEquals(new float[]{0,-512,-200},y,0);
		verify(npc,never()).getModel(); // Sleep pose and spot effects must not resize the artwork.
		verify(body,never()).scale(anyInt(),anyInt(),anyInt());
	}

	@Test
	public void pendingBodyAssetsRetryAndInvalidGeometryDoesNotProduceAScale()
	{
		Client client = mock(Client.class);
		NPC npc = mock(NPC.class);
		NPCComposition composition = mock(NPCComposition.class);
		when(npc.getComposition()).thenReturn(composition);
		when(composition.getModels()).thenReturn(new int[]{10});
		EVBloatModelFactory factory = new EVBloatModelFactory(client);
		assertNull(factory.scaleFor(npc));
		ModelData body = mock(ModelData.class);
		when(client.loadModelData(10)).thenReturn(body);
		when(body.getVerticesY()).thenReturn(new float[]{0,-700});
		assertEquals(700 / EVBloatModelFactory.BASE_HEIGHT,factory.scaleFor(npc),0.000001);
		when(body.getVerticesY()).thenReturn(new float[]{Float.NaN,-700});
		assertNull(factory.scaleFor(npc));
	}
}

package com.evbloat;

import java.io.PrintWriter;
import java.io.IOException;
import java.util.Locale;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;

/** Exports the actual procedural animation for an offline artwork preview. Not a game screenshot. */
public class MeshPreview
{
	public static void main(String[] args) throws Exception
	{
		export(args[0], false, false);
		export(Paths.get(args[0]).resolveSibling("sleep.json").toString(), true, false);
		export(Paths.get(args[0]).resolveSibling("slouch.json").toString(), true, true);
	}

	private static void export(String output, boolean sleeping, boolean kneeling) throws Exception
	{
		try (PrintWriter writer = new PrintWriter(Files.newBufferedWriter(Paths.get(output), StandardCharsets.UTF_8)))
		{
			writer.print('[');
			for (int frame = 0; frame < 32; frame++)
			{
				if (frame != 0) { writer.print(','); }
				writer.print('[');
				boolean first = true;
				for (EVBloatMesh.Triangle triangle : EVBloatMesh.pose(frame * Math.PI * 2 / 32, !sleeping, sleeping, kneeling).getFaces())
				{
					if (!first) { writer.print(','); }
					first = false;
					writer.print("[" + triangle.color);
					for (EVBloatMesh.Vec vertex : new EVBloatMesh.Vec[]{triangle.a, triangle.b, triangle.c})
					{
						writer.printf(Locale.ROOT, ",%.3f,%.3f,%.3f", vertex.x, vertex.y, vertex.z);
					}
					writer.print(']');
				}
				writer.print(']');
			}
			writer.print(']');
			if (writer.checkError()) { throw new IOException("Mesh preview export failed"); }
		}
	}
}
